import{_ as o,r as a,o as p,c as l,e as n,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Локализация - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, как переводить сообщения внутри CMS-тем.","frontmatter":{"subtitle":"Узнайте, как переводить сообщения внутри CMS-тем."},"headers":[{"level":3,"title":"Структура файлов локализации","slug":"структура-фаилов-локализации","link":"#структура-фаилов-локализации","children":[{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}],"relativePath":"3.x/ru/cms/themes/localization.md","filePath":"3.x/ru/cms/themes/localization.md"}'),i={name:"3.x/ru/cms/themes/localization.md"};function m(u,s,d,g,h,k){const e=a("pre-heading"),t=a("post-heading");return p(),l("div",null,[n(e),s[0]||(s[0]=c("h1",null,"Локализация",-1)),n(t),s[1]||(s[1]=r(`<div class="custom-block aside"><p>Ознакомьтесь со <a href="./../resources/multisite.html">статьёй о мультисайте</a>, чтобы узнать, как установить активный язык для вашего сайта.</p></div><p>Темы могут предоставлять ключи локализации через файлы, размещённые в поддиректории <strong>lang</strong> директории темы. Эти ключи локализации регистрируются автоматически и могут использоваться внутри содержимого темы или в качестве меток форм панели администрирования аналогично <a href="./../../extend/system/localization.html">локализации плагинов</a>.</p><h3 id="структура-фаилов-локализации"><a href="#структура-фаилов-локализации" class="header-anchor">#</a> Структура файлов локализации</h3><p>Ниже приведён пример директории <strong>lang</strong> темы.</p><pre class="dir-container"><code><p>├── themes
|   └── website
|       └── <code>lang</code>  <em>← Директория локализации</em>
|           ├── en.json  <em>← Файл локализации</em>
|           └── fr.json  <em>← Файл локализации</em></p>
</code></pre><p>Файл локализации представляет собой JSON-файл, в котором строки используют перевод «по умолчанию» в качестве ключа. Например, если ваше приложение имеет французский перевод, вам следует создать файл <code>lang/fr.json</code>.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;I love programming.&quot;</span><span class="token operator">:</span> <span class="token string">&quot;j&#39;adore programmer&quot;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы также можете определять ключи на основе кодов, используя полный языковой ключ в JSON-файле, например, <code>theme.options.website_name</code> для темы <strong>acme</strong>:</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;theme.options.website_name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;October CMS&quot;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Доступ к языковым строкам в файлах темы осуществляется с помощью Twig-фильтра <code>trans</code>.</p><div class="custom-block tip"><p>Ознакомьтесь с <a href="./../../markup/filter/trans.html">руководством по разметке</a>, чтобы узнать больше о переводах в Twig.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- j&#39;adore programmer --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>I love programming.<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>trans <span class="token delimiter punctuation">}}</span></span>

<span class="token comment">&lt;!-- October CMS --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>theme.options.website_name<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>trans <span class="token delimiter punctuation">}}</span></span>
</code></pre></div></div><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4><div class="custom-block also"><ul><li><a href="./../resources/multisite.html">Мультисайт</a></li><li><a href="./../../extend/system/localization.html">Локализация плагинов</a></li></ul></div>`,13))])}const v=o(i,[["render",m]]);export{f as __pageData,v as default};
